use vstd::prelude::*;

verus! {
    // Copy all elements of a Vec<T> (where T: Copy) into a new Vec<T>,
    // preserving order and not modifying the input.
    fn copy<T: Copy>(a: &Vec<T>) -> (res: Vec<T>)
        ensures
            // The result has the same length as the input
            res.len() == a.len(),
            // Every element at position i is the same in res and a
            forall |i: usize| i < a.len() ==> res[i] == a[i],
    {
        let mut res: Vec<T> = Vec::new();
        let mut i: usize = 0;

        // Build res by pushing each element of a in order.
        while i < a.len()
            invariant
                // i never exceeds the original length
                i <= a.len(),
                // We've pushed exactly i elements so far
                res.len() == i,
                // For all j<i, res[j] == a[j]
                forall |j: usize| j < i ==> res[j] == a[j],
            decreases a.len() - i,
        {
            // push the i-th element of a onto res
            res.push(a[i]);
            i = i + 1;
        }

        res
    }
}

fn main() {
    // example usage
    let v = Vec::from_slice(&[1, 2, 3, 4]);
    let w = copy(&v);
    assert!(w.len() == 4);
    assert!(w[0] == 1);
    assert!(w[1] == 2);
    assert!(w[2] == 3);
    assert!(w[3] == 4);
}